interface.definition:
a!localVariables(
  local!selected,
  local!statusId: if(
    a!isNullOrEmpty(local!selected),
    null,
    index(
      index(
        #"_a-0000ee91-8c80-8000-9c19-011c48011c48_707843"(statusName: local!selected.status),
        1,
        {}
      ),
      #"urn:appian:record-field:v1:c35e96c9-f57b-49f6-881c-3415513b6038/a3b69650-3581-4c1c-84a0-fb8f1c0fe830",
      ""
    )
  ),
  #"SYSTEM_SYSRULES_columnsLayout"(
    columns: {
      #"SYSTEM_SYSRULES_columnLayout"(
        contents: {
          #"SYSTEM_SYSRULES_ButtonLayout"(
            primaryButtons: {
              #"SYSTEM_SYSRULES_buttonWidget_v1"(
                label: "CLEAR STATUS",
                icon: "filter",
                value: null,
                saveInto: local!selected,
                style: "LINK",
                showWhen: a!isNotNullOrEmpty(local!selected)
              )
            }
          ),
          #"SYSTEM_SYSRULES_pieChartField"(
            data: #"SYSTEM_SYSRULES_recordData"(
              recordType: #"urn:appian:record-type:v1:25a53a8b-1fcd-4d3e-b4c9-8d762db65fff",
              filters: #"SYSTEM_SYSRULES_queryLogicalExpression"(
                operator: "AND",
                filters: {
                  #"SYSTEM_SYSRULES_queryFilter"(
                    field: #"urn:appian:record-field:v1:25a53a8b-1fcd-4d3e-b4c9-8d762db65fff/a1ec90ce-b471-45c3-a185-8b8c6a6db25c",
                    operator: "=",
                    value: ri!clientName
                  )
                },
                ignoreFiltersWithEmptyValues: true
              )
            ),
            loadDataAsync: true(),
            config: #"SYSTEM_SYSRULES_pieChartConfig"(
              primaryGrouping: #"SYSTEM_SYSRULES_grouping"(
                field: #"urn:appian:record-field:v1:25a53a8b-1fcd-4d3e-b4c9-8d762db65fff/5fcb7ac8-c71f-436b-9092-8f98ec3cf50a/35e3991c-c61d-418b-8ec0-3dbfde02d710",
                alias: "status"
              ),
              measures: {
                #"SYSTEM_SYSRULES_measure"(
                  function: "COUNT",
                  field: #"urn:appian:record-field:v1:25a53a8b-1fcd-4d3e-b4c9-8d762db65fff/84d33e15-9799-44e7-ae79-0ed85b5842bd",
                  alias: "count"
                )
              },
              dataLimit: 500,
              link: #"SYSTEM_SYSRULES_dynamicLink"(
                value: fv!selection,
                saveInto: { local!selected }
              )
            ),
            labelPosition: "ABOVE",
            showDataLabels: true,
            showTooltips: true,
            showAsPercentage: false,
            allowImageDownload: true,
            colorScheme: "RAINFOREST",
            style: "DONUT",
            seriesLabelStyle: "ON_CHART",
            refreshAfter: "RECORD_ACTION"
          )
        },
        width: if(
          a!isNullOrEmpty(local!selected),
          "WIDE",
          "MEDIUM"
        )
      ),
      #"SYSTEM_SYSRULES_columnLayout"(
        contents: {
          #"SYSTEM_SYSRULES_sectionLayout_v1"(
            label: "View Details for Status: " & index(local!selected, "status", ""),
            labelIcon: "eye",
            labelColor: #"_a-0000ee91-8c80-8000-9c19-011c48011c48_710392"[3],
            contents: {},
            divider: "ABOVE",
            dividerColor: "#800080",
            marginAbove: "LESS",
            marginBelow: "NONE"
          ),
          #"SYSTEM_SYSRULES_gridField_v1"(
            data: #"SYSTEM_SYSRULES_recordData"(
              recordType: #"urn:appian:record-type:v1:25a53a8b-1fcd-4d3e-b4c9-8d762db65fff",
              filters: {
                #"SYSTEM_SYSRULES_queryFilter"(
                  field: #"urn:appian:record-field:v1:25a53a8b-1fcd-4d3e-b4c9-8d762db65fff/5fcb7ac8-c71f-436b-9092-8f98ec3cf50a/35e3991c-c61d-418b-8ec0-3dbfde02d710",
                  operator: "=",
                  value: local!selected.status
                )
              }
            ),
            columns: {
              #"SYSTEM_SYSRULES_gridColumn"(
                label: if(
                  contains({ 7, 11 }, tointeger(local!statusId)),
                  "DB ID",
                  "Request Id"
                ),
                value: if(
                  contains({ 7, 11 }, tointeger(local!statusId)),
                  fv!row[#"urn:appian:record-field:v1:25a53a8b-1fcd-4d3e-b4c9-8d762db65fff/2eeebf8c-4bbc-4c61-acda-4b54f166bbc5"],
                  fv!row[#"urn:appian:record-field:v1:25a53a8b-1fcd-4d3e-b4c9-8d762db65fff/84d33e15-9799-44e7-ae79-0ed85b5842bd"]
                )
              ),
              #"SYSTEM_SYSRULES_gridColumn"(
                label: "Procedure Name",
                value: #"SYSTEM_SYSRULES_linkField"(
                  links: #"SYSTEM_SYSRULES_recordLink"(
                    label: if(
                      contains({ 7, 11 }, tointeger(local!statusId)),
                      fv!row[#"urn:appian:record-field:v1:25a53a8b-1fcd-4d3e-b4c9-8d762db65fff/ce9d5f63-2dbe-4e2b-b3af-f46716e06cde"],
                      fv!row[#"urn:appian:record-field:v1:25a53a8b-1fcd-4d3e-b4c9-8d762db65fff/ce9d5f63-2dbe-4e2b-b3af-f46716e06cde"] & " (Id: " & fv!row[#"urn:appian:record-field:v1:25a53a8b-1fcd-4d3e-b4c9-8d762db65fff/2eeebf8c-4bbc-4c61-acda-4b54f166bbc5"] & ") "
                    ),
                    recordType: #"urn:appian:record-type:v1:25a53a8b-1fcd-4d3e-b4c9-8d762db65fff",
                    identifier: fv!row[#"urn:appian:record-field:v1:25a53a8b-1fcd-4d3e-b4c9-8d762db65fff/84d33e15-9799-44e7-ae79-0ed85b5842bd"]
                  )
                )
              ),
              #"SYSTEM_SYSRULES_gridColumn"(
                label: "Business Area",
                value: fv!row[#"urn:appian:record-field:v1:25a53a8b-1fcd-4d3e-b4c9-8d762db65fff/7bd8ff87-9164-4bc2-9a78-306be9165f5b/47c4bd10-df58-4f0b-83df-f89480862206"],
                showWhen: tointeger(local!statusId) = 11
              ),
              #"SYSTEM_SYSRULES_gridColumn"(
                label: "Published Location",
                value: fv!row[#"urn:appian:record-field:v1:25a53a8b-1fcd-4d3e-b4c9-8d762db65fff/31663556-1bc6-4710-83df-d436f85f4046/9e58b29f-d280-4389-abf1-446bdf130318"],
                showWhen: tointeger(local!statusId) = 7
              ),
              #"SYSTEM_SYSRULES_gridColumn"(
                label: "Business Area",
                value: fv!row[#"urn:appian:record-field:v1:25a53a8b-1fcd-4d3e-b4c9-8d762db65fff/7bd8ff87-9164-4bc2-9a78-306be9165f5b/47c4bd10-df58-4f0b-83df-f89480862206"],
                showWhen: tointeger(local!statusId) = 7
              ),
              #"SYSTEM_SYSRULES_gridColumn"(
                label: if(
                  contains({ 7, 11 }, tointeger(local!statusId)),
                  "Publisher Comments",
                  if(
                    tointeger(local!statusId)=8,
                    "Cancel Reason",
                    "Change Reason"
                  )
                ),
                value: if(
                  contains({ 7, 11 }, tointeger(local!statusId)),
                  index(
                    #"_a-0000ee91-8c80-8000-9c19-011c48011c48_710029"(
                      requestId: fv!row[#"urn:appian:record-field:v1:25a53a8b-1fcd-4d3e-b4c9-8d762db65fff/84d33e15-9799-44e7-ae79-0ed85b5842bd"],
                      commentTypeId: 8,
                      fields: {
                        #"urn:appian:record-field:v1:4ebda985-0ea1-46b1-ad74-4fda292bf101/6cd93700-89c8-4fc5-b6ab-7bcf2c24b258"
                      }
                    ),
                    #"urn:appian:record-field:v1:4ebda985-0ea1-46b1-ad74-4fda292bf101/6cd93700-89c8-4fc5-b6ab-7bcf2c24b258",
                    ""
                  ),
                  if(
                    tointeger(local!statusId)=8,
                    #"_a-0000ee91-8c80-8000-9c19-011c48011c48_712060"(
                      description: fv!row[#"urn:appian:record-field:v1:25a53a8b-1fcd-4d3e-b4c9-8d762db65fff/73e6229f-4f40-44f5-b819-dbcfabbebbf5"]
                    ),
                    #"_a-0000ee91-8c80-8000-9c19-011c48011c48_712060"(
                      description: fv!row[#"urn:appian:record-field:v1:25a53a8b-1fcd-4d3e-b4c9-8d762db65fff/1b2b2b4c-80a7-4071-acb4-31d1b7a08274"]
                    )
                  )

                )
              ),
              #"SYSTEM_SYSRULES_gridColumn"(
                label: if(
                  tointeger(local!statusId) = 7,
                  "Publisher",
                  "Initiated by"
                ),
                value: if(
                  tointeger(local!statusId) = 7,
                  #"_a-0000ee91-8c80-8000-9c19-011c48011c48_710252"(
                    groupOrUser: fv!row[#"urn:appian:record-field:v1:25a53a8b-1fcd-4d3e-b4c9-8d762db65fff/31663556-1bc6-4710-83df-d436f85f4046/f1ae0ed0-4b6b-461b-9dba-f4905e489e6a"]
                  ),
                  fv!row[#"urn:appian:record-field:v1:25a53a8b-1fcd-4d3e-b4c9-8d762db65fff/3c5ff9b9-856c-40e1-a70a-9a1d2321120a"] & " - " & #"_a-0000ee91-8c80-8000-9c19-011c48011c48_711994"(
                    dateTime: fv!row[#"urn:appian:record-field:v1:25a53a8b-1fcd-4d3e-b4c9-8d762db65fff/0d0cd7e7-1e23-47c9-8dd2-f5dc63914a31"]
                  )
                ),
                showWhen: not(
                  contains({ 7, 11 }, tointeger(local!statusId))
                )
              ),
              #"SYSTEM_SYSRULES_gridColumn"(
                label: "Effective Date",
                value: fv!row[#"urn:appian:record-field:v1:25a53a8b-1fcd-4d3e-b4c9-8d762db65fff/31663556-1bc6-4710-83df-d436f85f4046/f4a94048-c2f5-4b78-aa1a-b95d2162609b"],
                showWhen: contains({ 7, 11 }, tointeger(local!statusId))
              )
            },
            userFilters: {
              if(
                tointeger(local!statusId) = 7,
                #"urn:appian:user-filter:v1:25a53a8b-1fcd-4d3e-b4c9-8d762db65fff/4db1ee29-8f42-4c94-91f4-a91f20a8e3e9",
                #"urn:appian:user-filter:v1:25a53a8b-1fcd-4d3e-b4c9-8d762db65fff/f08e9d8f-2268-47a0-a265-cbfbf33a3ee6"
              )
            },
            showExportButton: true()
          )
        },
        showWhen: not(a!isNullOrEmpty(local!selected))
      )
    }
  )
)
